local BookThreadReelMaker = {}
local PRODUCTS = {
    iron_bookthreadreel = { name = "Železni vitica za knjigoveške niti", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni vitica za knjigoveške niti za knjigoveze." },
    bronze_bookthreadreel = { name = "Bronast vitica za knjigoveške niti", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast vitica za knjigoveške niti za knjigoveze." },
    silver_bookthreadreel = { name = "Srebrn vitica za knjigoveške niti", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn vitica za knjigoveške niti za knjigoveze." },
    gilded_bookthreadreel = { name = "Pozlačen vitica za knjigoveške niti", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen vitica za knjigoveške niti za knjigoveze." },
    jewel_set_bookthreadreel = { name = "Draguljast vitica za knjigoveške niti", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast vitica za knjigoveške niti za knjigoveze." },
    royal_sovereign_bookthreadreel = { name = "Kraljevski suveren vitica za knjigoveške niti", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren vitica za knjigoveške niti z biseri za krono." },
}
local BUILDINGS = {
    bookthreadreel_workshop = { name = "Bookthreadreel delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    bookthreadreel_house = { name = "Bookthreadreel hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_bookthreadreel_atelier = { name = "Mojstrski bookthreadreel atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_bookthreadreel_palace = { name = "Suverena bookthreadreel palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BookThreadReelMaker.ironStock=12; BookThreadReelMaker.bronzeStock=10; BookThreadReelMaker.woodStock=16; BookThreadReelMaker.leatherStock=10; BookThreadReelMaker.silverStock=8; BookThreadReelMaker.goldStock=6; BookThreadReelMaker.jewelStock=4; BookThreadReelMaker.pearlStock=4
BookThreadReelMaker.productStock = {}; BookThreadReelMaker.buildings = {}; BookThreadReelMaker.maker = nil; BookThreadReelMaker.activeMaking = {}; BookThreadReelMaker.totalProducts = 0; BookThreadReelMaker.dayTimer = 0
function BookThreadReelMaker.init() BookThreadReelMaker.ironStock=12; BookThreadReelMaker.bronzeStock=10; BookThreadReelMaker.woodStock=16; BookThreadReelMaker.leatherStock=10; BookThreadReelMaker.silverStock=8; BookThreadReelMaker.goldStock=6; BookThreadReelMaker.jewelStock=4; BookThreadReelMaker.pearlStock=4; BookThreadReelMaker.productStock={}; BookThreadReelMaker.buildings={}; BookThreadReelMaker.maker=nil; BookThreadReelMaker.activeMaking={}; BookThreadReelMaker.totalProducts=0; BookThreadReelMaker.dayTimer=0; print("[BookThreadReelMaker] Royal Book Thread Reel Maker System initialized (6 products, 4 buildings)") end
function BookThreadReelMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookThreadReelMaker.maker={name=n or ("Vitičar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vitičar najet: %s (spretnost: %d)",BookThreadReelMaker.maker.name,s),"success") end; return true end
function BookThreadReelMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookThreadReelMaker.build(id) local ok,e=BookThreadReelMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookThreadReelMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookThreadReelMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookThreadReelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookThreadReelMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookThreadReelMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookThreadReelMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookThreadReelMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookThreadReelMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookThreadReelMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookThreadReelMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookThreadReelMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookThreadReelMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookThreadReelMaker.buildings==0 then return false,"Potrebna vitična delavnica" end; if not BookThreadReelMaker.maker then return false,"Potreben vitičar" end; return true end
function BookThreadReelMaker.make(pt,qty) qty=qty or 1; local ok,e=BookThreadReelMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookThreadReelMaker.ironStock=BookThreadReelMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookThreadReelMaker.bronzeStock=BookThreadReelMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookThreadReelMaker.woodStock=BookThreadReelMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookThreadReelMaker.leatherStock=BookThreadReelMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookThreadReelMaker.silverStock=BookThreadReelMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookThreadReelMaker.goldStock=BookThreadReelMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookThreadReelMaker.jewelStock=BookThreadReelMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookThreadReelMaker.pearlStock=BookThreadReelMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookThreadReelMaker.maker then t=math.max(1,t-math.floor(BookThreadReelMaker.maker.skill/13)) end; table.insert(BookThreadReelMaker.activeMaking,{id="bookthreadreel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookThreadReelMaker.completeMaking(m) local q=1.0+(BookThreadReelMaker.getQualityBonus()/100); if BookThreadReelMaker.maker then q=q+(BookThreadReelMaker.maker.skill/140) end; q=math.min(2.5,q); BookThreadReelMaker.productStock[m.productType]=(BookThreadReelMaker.productStock[m.productType] or 0)+m.quantity; BookThreadReelMaker.totalProducts=BookThreadReelMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookThreadReelMaker.maker then BookThreadReelMaker.maker.itemsMade=BookThreadReelMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookThreadReelMaker.maker.skill=math.min(100,BookThreadReelMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vitica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookthreadreel.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookThreadReelMaker.update(dt) if not _G.state then return end; BookThreadReelMaker.dayTimer=BookThreadReelMaker.dayTimer+dt; if BookThreadReelMaker.dayTimer>=30 then BookThreadReelMaker.dayTimer=0; for i=#BookThreadReelMaker.activeMaking,1,-1 do local m=BookThreadReelMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookThreadReelMaker.completeMaking(m); table.remove(BookThreadReelMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookThreadReelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookThreadReelMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookThreadReelMaker.getStats() return {ironStock=BookThreadReelMaker.ironStock,bronzeStock=BookThreadReelMaker.bronzeStock,woodStock=BookThreadReelMaker.woodStock,leatherStock=BookThreadReelMaker.leatherStock,silverStock=BookThreadReelMaker.silverStock,goldStock=BookThreadReelMaker.goldStock,jewelStock=BookThreadReelMaker.jewelStock,pearlStock=BookThreadReelMaker.pearlStock,productStock=BookThreadReelMaker.productStock,numBuildings=#BookThreadReelMaker.buildings,hasMaker=BookThreadReelMaker.maker~=nil,makerName=BookThreadReelMaker.maker and BookThreadReelMaker.maker.name or "—",makerSkill=BookThreadReelMaker.maker and BookThreadReelMaker.maker.skill or 0,activeMaking=#BookThreadReelMaker.activeMaking,totalProducts=BookThreadReelMaker.totalProducts} end
return BookThreadReelMaker
